import java.util.Arrays;

public class PivotPartitionerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            int[] mixed = {5, 1, 9, 3, 7};
            check("partition({5,1,9,3,7}, 5) count", 2, PivotPartitioner.partition(mixed, 5));
            check("partition({5,1,9,3,7}, 5) array", "[1, 3, 5, 9, 7]", Arrays.toString(mixed));

            int[] allSmall = {1, 2, 3};
            check("all below pivot count", 3, PivotPartitioner.partition(allSmall, 10));
            check("all below pivot array", "[1, 2, 3]", Arrays.toString(allSmall));

            int[] duplicates = {3, 3, 1, 3};
            check("pivot duplicates count", 1, PivotPartitioner.partition(duplicates, 3));
            check("pivot duplicates array", "[1, 3, 3, 3]", Arrays.toString(duplicates));

            int[] negatives = {-1, 4, -5, 0};
            PivotPartitioner.partition(negatives, 0);
            check("negatives keep relative order", "[-1, -5, 4, 0]", Arrays.toString(negatives));

            check("empty array returns 0", 0, PivotPartitioner.partition(new int[] {}, 4));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected exception: " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

