public class PivotPartitioner {

    public static int partition(int[] values, int pivot) {
        int[] scratch = new int[values.length];
        int next = 0;
        for (int value : values) {
            if (value < pivot) {
                scratch[next] = value;
                next++;
            }
        }
        int smallCount = next;
        for (int value : values) {
            if (value >= pivot) {
                scratch[next] = value;
                next++;
            }
        }
        for (int i = 0; i < values.length; i++) {
            values[i] = scratch[i];
        }
        return smallCount;
    }
}
